      "ballot_id": "B005",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction turned fragile quantum information into a physically protected resource and established the conceptual basis for fault-tolerant quantum computing. Its influence extends well beyond any one hardware platform.",
        "attribution": "Kitaev's topological code and fault-tolerance framework, Steane's code, and Shor's error-correcting code and algorithmic work are distinct foundational contributions that together support the stated discovery.",
        "maturity": "The theory is mature and has been tested in increasingly capable experiments, though large-scale fault-tolerant computation remains unachieved.",
        "uncertainties": [
          "The broad label combines several advances whose boundaries and relative credit could be drawn differently.",
          "The practical scale and robustness of fault-tolerant operation are still developing."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made strong, controllable light–matter interaction accessible in engineered superconducting devices. It opened a new regime for quantum optics and became a central platform for studying and controlling quantum systems.",
        "attribution": "Blais provided key theoretical proposals; Wallraff and Schoelkopf were central to early experimental realization and development. Girvin also made important theoretical contributions, so limiting recognition to three requires a difficult boundary.",
        "maturity": "The core phenomena have been demonstrated and developed across many laboratories over decades. Applications continue to advance, while scalable fault-tolerant computing remains an open challenge.",
        "uncertainties": [
          "The discovery is a broad body of work involving many contributors, including experimental teams and theorists beyond the three proposed."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory supplied exact methods and a deep organizing framework for critical phenomena, with lasting influence across statistical physics and quantum field theory.",
        "attribution": "Belavin, Polyakov, and Zamolodchikov are strongly associated with the foundational formulation and exact results described here.",
        "maturity": "The framework and its consequences have been extensively developed and confirmed through applications to critical systems.",
        "uncertainties": [
          "The discovery's scope overlaps with broader developments in conformal symmetry and critical phenomena involving additional researchers."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought atomic frequency standards to a new level of precision and control, enabling stringent tests of fundamental physics as well as improved timekeeping.",
        "attribution": "Katori and Ye independently led complementary approaches that were central to establishing the field.",
        "maturity": "The technology is highly mature, with reproducible performance improvements and use by multiple groups.",
        "uncertainties": [
          "A prize would need to distinguish the key conceptual advances from the broader international effort that refined clock performance."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Charles L. Kane",
        "Laurens W. Molenkamp",
        "Qi-Kun Xue"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall and quantum anomalous Hall effects established topological insulators as a new class of quantum matter and made topological transport observable in solids.",
        "attribution": "Kane's theory and the experimental demonstrations associated with Molenkamp and Xue anchor the two effects named in this combined discovery.",
        "maturity": "The effects have been observed and studied in multiple material systems, although sample quality and operating conditions remain important practical constraints.",
        "uncertainties": [
          "The ballot combines two related effects with distinct theoretical and experimental histories, complicating the division of credit."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Juan Ignacio Cirac",
        "Markus Greiner"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice experiments made controlled quantum many-body simulation possible and enabled direct study of Hubbard-model physics in regimes difficult to access otherwise.",
        "attribution": "Cirac's theoretical foundations and the experimental advances of Bloch and Greiner represent complementary contributions to the platform and its early landmark results.",
        "maturity": "The platform is well established and has produced a substantial body of reproducible results, though the scope of what it can reliably establish continues to expand.",
        "uncertainties": [
          "Zoller and many other theorists and experimentalists contributed to the underlying proposals and development, making a three-person attribution selective."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and programmable neutral-atom arrays provide a powerful route to controlled many-body physics and quantum simulation, with a striking combination of scalability and individual addressability.",
        "attribution": "Lukin's blockade work and the experimental development of large, controllable arrays by Browaeys and Saffman are central contributions represented here.",
        "maturity": "The platform has advanced rapidly, but its long-term reproducibility, error correction, and relative standing among competing quantum hardware approaches are still being established.",
        "uncertainties": [
          "The field is comparatively young, and the lasting scope of its foundational impact is not yet clear.",
          "The proposed names do not exhaust the major experimental and theoretical contributions."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cooling and controlling mechanical oscillators near their quantum ground state made macroscopic quantum behavior experimentally accessible and established optomechanics as a rich field.",
        "attribution": "Cleland, Aspelmeyer, and Kippenberg represent important complementary advances in mechanical quantum control and optomechanics.",
        "maturity": "Ground-state preparation and coherent control have been achieved in several systems, but broad, robust demonstrations of macroscopic quantum behavior remain an active pursuit.",
        "uncertainties": [
          "The ballot spans multiple experimental approaches, and the extent to which these advances form one prize-sized discovery is debatable."
        ]
      }
    }
  ]
